// The Oakhaven family of companies. Every company, logo and figure here is
// fictional demo content. Logos are generated by `npm run images` from the
// `LOGOS` list in scripts/images.mjs; replace them with real files in
// public/media/logos/ and point `logo` at them.

export type GroupId = 'industrial' | 'federal' | 'real-estate' | 'investment'

export type Company = {
  id: string
  name: string
  group: GroupId
  kind: 'Subsidiary' | 'Joint Venture' | 'Minority Investment' | 'Holding Company'
  logo: string
  url: string
  summary: string
  /** Small print under the summary: when and how the company joined. */
  source: string
}

export const GROUP_LABEL: Record<GroupId, string> = {
  industrial: 'Industrial Group',
  federal: 'Federal Group',
  'real-estate': 'Real Estate Group',
  investment: 'Investments',
}

